{
  "name": "Wasatch 光谱仪交互式命令行外壳",
  "name_en": "Wasatch Spectrometer Interactive Shell",
  "manufacturer": "",
  "description": "一个非物理的软件命令行工具，用于连接和操作 Wasatch 光谱仪设备。它主要服务于实验调试、交互式测试和数据采集，可执行连接设备、采集光谱、控制激光、管理暗谱、设置插值坐标轴以及平衡采集参数等操作。",
  "description_en": "A non-physical command-line software tool for connecting to and operating Wasatch spectrometer devices. It is mainly used for experiment debugging, interactive testing, and data acquisition, including device connection, spectrum capture, laser control, dark-spectrum management, interpolated axis setup, and acquisition balancing.",
  "tag_hints": [
    "command-line spectrometer control",
    "Raman spectroscopy",
    "spectrum acquisition",
    "laser enable control",
    "dark spectrum management",
    "interactive testing",
    "interpolated spectral axis"
  ],
  "actions": [
    {
      "action_name": "auto-usage",
      "description": "显示命令用法说明",
      "description_en": "show command usage information"
    },
    {
      "action_name": "auto-disconnected",
      "description": "显示或判断设备是否已断开连接",
      "description_en": "show or determine whether the device is disconnected"
    },
    {
      "action_name": "auto-has_input",
      "description": "检查是否有可用输入",
      "description_en": "check whether input is available"
    },
    {
      "action_name": "auto-read_bool",
      "description": "读取布尔值输入",
      "description_en": "read a boolean input value"
    },
    {
      "action_name": "auto-read_int",
      "description": "读取整数输入",
      "description_en": "read an integer input value"
    },
    {
      "action_name": "auto-read_float",
      "description": "读取浮点数输入",
      "description_en": "read a floating-point input value"
    },
    {
      "action_name": "auto-read_str",
      "description": "读取字符串输入",
      "description_en": "read a string input value"
    },
    {
      "action_name": "auto-display",
      "description": "显示消息",
      "description_en": "display a message"
    },
    {
      "action_name": "auto-configure_logging",
      "description": "配置日志记录",
      "description_en": "configure logging"
    },
    {
      "action_name": "auto-run",
      "description": "运行交互式命令循环",
      "description_en": "run the interactive command loop"
    },
    {
      "action_name": "auto-open",
      "description": "打开并连接可用光谱仪",
      "description_en": "open and connect to an available spectrometer"
    },
    {
      "action_name": "auto-run_gettor",
      "description": "执行获取类命令",
      "description_en": "run a getter-style command"
    },
    {
      "action_name": "auto-clear_dark",
      "description": "清除已保存的暗谱",
      "description_en": "clear the stored dark spectrum"
    },
    {
      "action_name": "auto-set_raman_intensity_correction_enable",
      "description": "启用或禁用拉曼强度校正",
      "description_en": "enable or disable Raman intensity correction"
    },
    {
      "action_name": "auto-srm_process",
      "description": "对光谱执行 SRM 处理",
      "description_en": "process a spectrum using SRM handling"
    },
    {
      "action_name": "auto-set_laser_enable",
      "description": "启用或禁用激光",
      "description_en": "enable or disable the laser"
    },
    {
      "action_name": "auto-generate_interpolated_x_axis",
      "description": "生成插值 x 轴",
      "description_en": "generate an interpolated x-axis"
    },
    {
      "action_name": "auto-set_interpolated_x_axis_cm",
      "description": "定义以 cm⁻¹ 为单位的插值 x 轴",
      "description_en": "define the interpolated x-axis in cm⁻¹"
    },
    {
      "action_name": "auto-set_interpolated_x_axis_nm",
      "description": "定义以 nm 为单位的插值 x 轴",
      "description_en": "define the interpolated x-axis in nm"
    },
    {
      "action_name": "auto-clear",
      "description": "清除当前外壳管理的状态或数据",
      "description_en": "clear the current shell-managed state or data"
    },
    {
      "action_name": "auto-balance_acquisition",
      "description": "平衡采集参数以接近目标强度",
      "description_en": "balance acquisition settings toward a target intensity"
    },
    {
      "action_name": "auto-get_line",
      "description": "获取一行输入",
      "description_en": "get an input line"
    },
    {
      "action_name": "auto-get_next_token",
      "description": "获取下一个输入标记",
      "description_en": "get the next input token"
    },
    {
      "action_name": "auto-get_dark",
      "description": "获取暗谱",
      "description_en": "get the dark spectrum"
    },
    {
      "action_name": "auto-get_spectrum",
      "description": "获取光谱",
      "description_en": "get the spectrum"
    },
    {
      "action_name": "auto-get_spectrum_save",
      "description": "获取并保存光谱",
      "description_en": "get and save the spectrum"
    },
    {
      "action_name": "auto-get_spectrum_pretty",
      "description": "获取格式化显示的光谱",
      "description_en": "get the spectrum in a formatted view"
    },
    {
      "action_name": "auto-get_all",
      "description": "获取全部状态信息",
      "description_en": "get all status information"
    }
  ]
}

